//! Ordered orchestration boundary for the local development loop.
//!
//! This module owns stage order and the committed-source boundary only. Stage
//! implementations remain with their existing migration, build, gate, and
//! publication owners and enter through [`DevStageRunner`].

pub mod activation;
#[cfg(target_os = "linux")]
pub mod command;
pub mod config;
#[cfg(target_os = "linux")]
pub mod coordinator;
pub mod environment;
#[cfg(target_os = "linux")]
pub mod observations;
pub mod read;
#[cfg(target_os = "linux")]
pub mod tui;
pub mod up;
pub mod verification_database;
pub mod verification_world;
#[cfg(target_os = "linux")]
pub mod watch;

use std::error::Error;
use std::fmt;

use config::DevConfig;
use read::DevRuntimeEndpoint;
use verification_database::VerificationDatabaseError;

/// Stable refusal code for a dirty worktree reaching committed-source work.
pub const DIRTY_WORKTREE_ERROR: &str = "dev-worktree-dirty";

/// Stable remedy for [`DIRTY_WORKTREE_ERROR`].
pub const COMMIT_WORKTREE_REMEDY: &str = "commit the worktree";

/// Exact stage order of one local development run.
pub const DEV_STAGE_ORDER: [DevStage; 12] = [
    DevStage::Migrate,
    DevStage::Introspect,
    DevStage::Generate,
    DevStage::Build,
    DevStage::Virtualize,
    // Apply and Acl carry the package to the project-environment database
    // BEFORE Admit, because component projection refuses with
    // source-package-not-applied against a database that does not hold the
    // package yet. The authoring chain writes to that same database (owner
    // ruling 2026-09-06, wamn-10yt.10.34), so the package must land first.
    DevStage::Apply,
    DevStage::Acl,
    DevStage::Admit,
    DevStage::Gate,
    DevStage::Publish,
    DevStage::Release,
    DevStage::Activate,
];

/// One stable stage identity in the development loop.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum DevStage {
    Migrate,
    Introspect,
    Generate,
    Build,
    Virtualize,
    Admit,
    Gate,
    Publish,
    Apply,
    Acl,
    Release,
    Activate,
}

impl DevStage {
    fn position(self) -> usize {
        DEV_STAGE_ORDER
            .iter()
            .position(|stage| *stage == self)
            .expect("every DevStage belongs to DEV_STAGE_ORDER")
    }

    /// Stable command-facing spelling of this stage.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Migrate => "migrate",
            Self::Introspect => "introspect",
            Self::Generate => "generate",
            Self::Build => "build",
            Self::Virtualize => "virtualize",
            Self::Admit => "admit",
            Self::Gate => "gate",
            Self::Publish => "publish",
            Self::Apply => "apply",
            Self::Acl => "acl",
            Self::Release => "release",
            Self::Activate => "activate",
        }
    }

    /// Source-integrity boundary this stage requires.
    pub const fn boundary(self) -> DevStageBoundary {
        match self {
            // Gate validates and returns a receipt; it writes nothing, so it
            // still runs from saved bytes. Admit does not: since the authoring
            // chain moved to the project-environment database it projects the
            // admitted component there, which is durable work
            // (wamn-10yt.10.34).
            Self::Migrate
            | Self::Introspect
            | Self::Generate
            | Self::Build
            | Self::Virtualize
            | Self::Gate => DevStageBoundary::SavedBytes,
            Self::Admit
            | Self::Publish
            | Self::Apply
            | Self::Acl
            | Self::Release
            | Self::Activate => DevStageBoundary::CommittedSource,
        }
    }
}

impl fmt::Display for DevStage {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.as_str())
    }
}

/// Source-integrity requirement at a stage boundary.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum DevStageBoundary {
    /// Saved worktree bytes may execute against disposable development state.
    SavedBytes,
    /// The stage can mint or deploy durable provenance and requires a commit.
    CommittedSource,
}

