            format!("{operation_name} {contract} must declare at least one typed field"),
        ));
    }
    let mut paths = BTreeSet::new();
    for field in fields {
        validate_contract_path(&field.path, operation_name)?;
        if !paths.insert(field.path.as_str()) {
