        }
        if !field.values.is_empty() {
            if field.ty != wamn_schema_introspection::ir::ColumnType::Text
                || field.values.iter().any(String::is_empty)
                || field.values.iter().collect::<BTreeSet<_>>().len() != field.values.len()
            {
