/// Exact saved-byte admission reused by later publication.
///
/// Fields stay private so callers cannot replace admitted facts, package
/// evidence, or component bytes independently. The receipt deliberately does
/// not implement `Clone`; retries borrow the same admission.
pub struct ComponentAdmissionReceipt {
    package_path: PathBuf,
    directory: PackageDirectory,
    component_bytes: Box<[u8]>,
    component: AdmittedComponent,
    requirements: Box<[ComponentConnectionRequirement]>,
    manifest_sha256: Box<str>,
    projection_hash: Box<str>,
}

impl fmt::Debug for ComponentAdmissionReceipt {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ComponentAdmissionReceipt")
            .field("package_id", &self.component.scope.package_id)
            .field("package_version", &self.component.scope.package_version)
            .field("component", &self.component.component)
            .field("component_digest", &self.component.component_digest)
            .field("component_bytes_len", &self.component_bytes.len())
            .field("requirement_count", &self.requirements.len())
            .field("manifest_sha256", &self.manifest_sha256)
            .field("projection_hash", &self.projection_hash)
            .finish_non_exhaustive()
    }
}

impl ComponentAdmissionReceipt {
    /// Exact package identity carried by the admitted component facts.
    pub fn package_id(&self) -> &str {
        &self.component.scope.package_id
    }

    /// Exact package version carried by the admitted component facts.
    pub fn package_version(&self) -> &str {
        &self.component.scope.package_version
    }

    /// Package-local component name bound to the admitted bytes.
    pub fn component(&self) -> &str {
        &self.component.component
    }

    /// SHA-256 identity derived from the exact admitted bytes.
    pub fn component_digest(&self) -> &str {
        &self.component.component_digest
    }
}

/// Validate saved component and package bytes without publication side effects.
pub fn admit_component(args: AdmitComponentArgs) -> anyhow::Result<ComponentAdmissionReceipt> {
    let directory = crate::apply_package::read_package_directory(&args.package)?;
    let package = plan_package_migrations(&directory, None)
        .context("validate strict package directory before component publication")?;
    let package_manifest =
        wamn_schema_generator::PackageManifest::from_slice(&directory.manifest_bytes)
            .context("parse strict package manifest before component publication")?;
    let component_bytes = std::fs::read(&args.component_bytes)
        .with_context(|| format!("read component bytes {}", args.component_bytes.display()))?;
    let declaration_bytes = std::fs::read(&args.declaration)
        .with_context(|| format!("read component declaration {}", args.declaration.display()))?;
    let declaration: ComponentDeclaration = serde_json::from_slice(&declaration_bytes)
        .with_context(|| format!("parse component declaration {}", args.declaration.display()))?;

    let engine = wamn_runtime::build_engine(&[]).context("build component admission engine")?;
    let facts = validate_component_admission(
        &engine,
        &component_bytes,
        wamn_runtime::component_admission::ComponentAdmissionRequest {
            declaration,
            admitted_platform_packages: args
                .admitted_platform_packages
                .into_iter()
                .collect::<BTreeSet<_>>(),
        },
    )
    .context("validate exact component bytes")?;
    let mut admitted = facts.component;
    ensure_component_package_matches(&admitted, &package.coordinate)?;
    let statement_facts =
        load_component_statement_facts(&args.package, &package_manifest, &admitted)?;
    bind_component_statement_facts(&mut admitted, statement_facts)
        .context("bind generated SQL facts to exact component operations")?;
    let requirements = facts
        .connections
        .iter()
        .map(|connection| portable_requirement(&admitted.component_digest, connection))
        .collect::<Vec<_>>();
    let projection_hash = admitted_projection_hash(&admitted, &requirements)?;

    Ok(ComponentAdmissionReceipt {
        package_path: args.package,
        directory,
        component_bytes: component_bytes.into_boxed_slice(),
        component: admitted,
        requirements: requirements.into_boxed_slice(),
        manifest_sha256: package.manifest_sha256.into_boxed_str(),
        projection_hash: projection_hash.into_boxed_str(),
    })
}

/// Project one opaque admission into a disposable verification database.
///
/// This verification-only write neither publishes component bytes nor reaches
/// the control plane. The receipt remains the sole source of projected facts.
pub async fn project_admitted_component_for_verification(
    admission: &ComponentAdmissionReceipt,
    verification_database_url: &str,
) -> anyhow::Result<()> {
    let verification_config: PgConfig = verification_database_url
        .parse()
        .context("parse verification-project database URL")?;
    persist_plane(
        &verification_config,
        ProjectionPlane::SourceProject,
        &admission.component,
        &admission.requirements,
        &admission.manifest_sha256,
        &admission.projection_hash,
        &admission.directory,
        &admission.package_path,
    )
    .await
    .map(|_| ())
}

/// Publish one exact admission and project its facts without rereading sources.
pub async fn publish_admitted_component(
    admission: &ComponentAdmissionReceipt,
    args: PublishAdmittedComponentArgs,
) -> anyhow::Result<()> {
    let admitted = &admission.component;
    let project_config: PgConfig = args
        .project_database_url
        .parse()
        .context("parse source-project database URL")?;
    let control_config: PgConfig = args
        .control_database_url
        .parse()
        .context("parse T1 control database URL")?;
    let project = require_exact_verification_projection(
        &project_config,
        admitted,
        &admission.requirements,
        &admission.manifest_sha256,
        &admission.projection_hash,
        &admission.directory,
        &admission.package_path,
    )
    .await?;
    let artifact = component_artifact_reference(&args.artifact_base, &admitted.component_digest)
        .context("derive component artifact reference")?;
    let reference = Reference::with_tag(
        artifact.registry().to_owned(),
        artifact.repository().to_owned(),
        artifact.tag().to_owned(),
    );
    let registry_credentials =
        read_registry_credentials(&args.registry_auth_file, artifact.registry())
            .context("load component registry push credential")?;
    let config_bytes = component_artifact_config_bytes(admitted);

    publish_and_verify(
        &reference,
        &args.artifact_base,
        args.insecure_registry,
        &admission.component_bytes,

