        let Some(left) = identifier(&tokens[index]) else {
            continue;
        };
        if tokens[index + 1] != Token::Dot {
            continue;
        }
        let Some(field) = identifier(&tokens[index + 2]) else {
            continue;
        };
        let Some(relation) = aliases
            .get(left)
            .map(String::as_str)
            .or_else(|| relations.contains_key(left).then_some(left))
