            | "into"
            | "is"
            | "join"
            | "key"
            | "left"
            | "limit"
            | "locked"
            | "materialized"
            | "no"
            | "not"
            | "nothing"
            | "null"
            | "of"
            | "on"
            | "or"
            | "order"
            | "returning"
            | "select"
            | "set"
            | "share"
            | "then"
