            depths[*candidate] == depth && identifier(&tokens[*candidate]) == Some("of")
        });
        let targets = if let Some(of) = of {
            let mut targets = Vec::new();
            for candidate in of + 1..end {
                if depths[candidate] < depth {
                    break;
                }
                if depths[candidate] != depth {
