python3 - <<'PY'
import json, hashlib, os

UUID = "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"
DAY = "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"
STATUS = ["scheduled", "arrived", "departed"]

def envelope(required, properties):
    return {
        "type": "array",
        "minItems": 1,
        "maxItems": 100,
        "items": {
            "type": "object",
            "required": ["request_id"] + required,
            "additionalProperties": False,
            "properties": dict({"request_id": {"type": "string", "minLength": 1}}, **properties),
        },
    }

OPS = {
    "carrier.create": {
        "wiring": "carrier_create",
        "interface": "wamn-dock:carrier/create@1.0.0",
        "path": "/carrier/create",
        "attachment": "wamn-dock-carrier-create-http",
        "schema": envelope(["name"], {"name": {"type": "string", "minLength": 1}}),
    },
    "dock.create": {
        "wiring": "dock_create",
        "interface": "wamn-dock:dock/create@1.0.0",
        "path": "/dock/create",
        "attachment": "wamn-dock-dock-create-http",
        "schema": envelope(["name"], {"name": {"type": "string", "minLength": 1}}),
    },
    "appointment.book": {
        "wiring": "appointment_book",
        "interface": "wamn-dock:appointment/book@1.0.0",
        "path": "/appointment/book",
        "attachment": "wamn-dock-appointment-book-http",
        "schema": envelope(
            ["idempotency_key", "carrier_id", "dock_id", "slot_start", "slot_end"],
            {
                "idempotency_key": {"type": "string", "minLength": 1},
                "carrier_id": {"type": "string", "pattern": UUID},
                "dock_id": {"type": "string", "pattern": UUID},
                "slot_start": {"type": "string", "minLength": 1},
                "slot_end": {"type": "string", "minLength": 1},
            },
        ),
    },
    "appointment.check_in": {
        "wiring": "appointment_check_in",
        "interface": "wamn-dock:appointment/check-in@1.0.0",
        "path": "/appointment/check_in",
        "attachment": "wamn-dock-appointment-check-in-http",
        "schema": envelope(
            ["appointment_id", "arrived_at"],
            {
                "appointment_id": {"type": "string", "pattern": UUID},
                "arrived_at": {"type": "string", "minLength": 1},
            },
        ),
    },
    "appointment.query": {
        "wiring": "appointment_query",
        "interface": "wamn-dock:appointment/query@1.0.0",
        "path": "/appointment/query",
        "attachment": "wamn-dock-appointment-query-http",
        "schema": envelope(
            ["dock_id", "day", "status"],
            {
                "dock_id": {"type": "string", "pattern": UUID},
                "day": {"type": "string", "pattern": DAY},
                "status": {"type": "string", "enum": STATUS},
            },
        ),
    },
}

root = "packages/dock/publication"

# wirings
for op, spec in OPS.items():
    doc = {
        "format-version": "0.1",
        "wiring-id": spec["wiring"],
        "version": 1,
        "entry": "operation",
        "nodes": {
            "operation": {
                "component": "dock",
                "interface-version": "0.1.0",
                "operation": spec["interface"],
                "terminal": "respond",
            }
        },
    }
    with open(f"{root}/wirings/{spec['wiring']}.json", "w") as handle:
        json.dump(doc, handle, indent=2)
        handle.write("\n")

# component declaration template
declaration = {
    "scope": {
        "tenant-id": "__TENANT_ID__",
        "package-id": "wamn_dock",
        "package-version": "1.0.0",
    },
    "component": "dock",
    "interface-version": "0.1.0",
    "operations": {
        spec["interface"]: {
            "registered-operation": spec["interface"],
            "input-ports": [{"name": "input", "schema": spec["schema"]}],
            "output-ports": [{"name": "main", "schema": {"type": "array"}}],
            "parameters": [],
        }
        for spec in OPS.values()
    },
    "connections": [],
}
with open(f"{root}/components/dock.json.in", "w") as handle:
    json.dump(declaration, handle, indent=2)
    handle.write("\n")

# attachments
attachments = {}
for spec in OPS.values():
    definition = {
        "id": spec["attachment"],
        "kind": "http",
        "route": {"path": spec["path"], "method": "POST"},
        "raw-body-bytes": {"maximum": 1048576},
        "input-schema": spec["schema"],
    }
    digest = "sha256:" + hashlib.sha256(
        json.dumps(definition, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    attachments[spec["attachment"]] = {
        "kind": "http",
        "package-id": "wamn_dock",
        "wiring-id": spec["wiring"],
        "wiring-version": 1,
        "definition-hash": digest,
        "definition": definition,
        "auth-policy": {"mode": "pat"},
        "registered-operation": spec["interface"],
    }
with open(f"{root}/attachments.json", "w") as handle:
    json.dump(attachments, handle, indent=2)
    handle.write("\n")

print("wrote", sorted(os.listdir(f"{root}/wirings")))
